<style> table { width:100%; border-collapse:collapse; margin-top:12px; } th, td { text-align:left; padding:10px 12px; border-bottom:1px solid #e0e0e0; font-size:14px; } th { background:#f5f5f5; font-weight:600; color:#555; } tr:hover td { background:#fafafa; } .badge { display:inline-block; padding:2px 8px; border-radius:4px; font-size:12px; font-weight:500; } .badge-aktif { background:#e8f5e9; color:#2e7d32; } .badge-nonaktif { background:#fce4ec; color:#c62828; } .badge-jenis { background:#e3f2fd; color:#1565c0; } .btn-add { display:inline-block; padding:8px 16px; background:#1a73e8; color:#fff; border-radius:6px; text-decoration:none; font-size:14px; font-weight:500; margin-bottom:12px; } .btn-sm { padding:4px 12px; border-radius:4px; font-size:12px; text-decoration:none; display:inline-block; margin-right:4px; } .btn-edit { background:#fff3e0; color:#e65100; } .btn-delete { background:#fce4ec; color:#c62828; border:none; cursor:pointer; font-size:12px; padding:4px 12px; border-radius:4px; } .filter-bar { display:flex; gap:12px; margin-bottom:16px; flex-wrap:wrap; align-items:flex-end; } .filter-bar input, .filter-bar select { padding:8px 12px; border:1px solid #d0d0d0; border-radius:6px; font-size:14px; } .filter-bar button { padding:8px 16px; background:#f5f5f5; border:1px solid #d0d0d0; border-radius:6px; cursor:pointer; font-size:14px; } .filter-bar button:hover { background:#e0e0e0; } </style> <h2 style="margin-bottom:16px;">Master OPT (Organisme Pengganggu Tanaman)</h2> <a href="/opt/create" class="btn-add">+ Tambah OPT</a> <form method="GET" action="/opt" class="filter-bar"> <div> <label style="font-size:12px;color:#888;display:block;">Jenis</label> <select name="jenis"> <option value="">Semua Jenis</option> <option value="hama" <?= $filterJenis === 'hama' ? 'selected' : '' ?>>Hama</option> <option value="penyakit" <?= $filterJenis === 'penyakit' ? 'selected' : '' ?>>Penyakit</option> <option value="gulma" <?= $filterJenis === 'gulma' ? 'selected' : '' ?>>Gulma</option> </select> </div> <div> <label style="font-size:12px;color:#888;display:block;">Status</label> <select name="aktif"> <option value="">Semua</option> <option value="1" <?= $filterAktif === '1' ? 'selected' : '' ?>>Aktif</option> <option value="0" <?= $filterAktif === '0' ? 'selected' : '' ?>>Nonaktif</option> </select> </div> <div> <label style="font-size:12px;color:#888;display:block;">Cari</label> <input type="text" name="q" placeholder="Cari nama OPT..." value="<?= \App\Core\Security::e($filterSearch) ?>"> </div> <div> <label style="font-size:12px;color:#888;display:block;">&nbsp;</label> <button type="submit">Filter</button> </div> </form> <table> <thead> <tr> <th>Nama OPT</th> <th>Jenis</th> <th>ETL Acuan</th> <th>Satuan</th> <th>Status</th> <th>Aksi</th> </tr> </thead> <tbody> <?php foreach ($data as $opt): ?> <tr> <td><?= \App\Core\Security::e($opt['nama_opt']) ?></td> <td><span class="badge badge-jenis"><?= \App\Core\Security::e($opt['jenis']) ?></span></td> <td><?= $opt['etl_acuan'] !== null ? \App\Core\Security::e((string) $opt['etl_acuan']) : '-' ?></td> <td><?= \App\Core\Security::e($opt['satuan_etl'] ?? '-') ?></td> <td><span class="badge <?= ($opt['aktif'] ?? 1) ? 'badge-aktif' : 'badge-nonaktif' ?>"><?= ($opt['aktif'] ?? 1) ? 'Aktif' : 'Nonaktif' ?></span></td> <td> <a href="/opt/<?= (int) $opt['id'] ?>/edit" class="btn-sm btn-edit">Edit</a> <form method="POST" action="/opt/<?= (int) $opt['id'] ?>/delete" style="display:inline" onsubmit="return confirm('Hapus/nonaktifkan OPT ini?')"> <?= \App\Core\Security::csrfField() ?> <button type="submit" class="btn-delete">Hapus</button> </form> </td> </tr> <?php endforeach; ?> <?php if (count($data) === 0): ?> <tr><td colspan="6" style="text-align:center;color:#999;padding:24px;">Belum ada data OPT.</td></tr> <?php endif; ?> </tbody> </table> 